  source: 'wikipathways',
  examples: `Get the species currently in WikiPathways with their respective URI's SELECT DISTINCT ?organism ( str ( ?label ) as ?name ) WHERE { ?concept wp : organism ?organism ; wp : organismName ?label . } Open List pathways and their species SELECT DISTINCT ( str ( ?title ) as ?pathway ) ( str ( ?label ) as ?organism ) WHERE { ?pw dc : title ?title ; wp : organism ?organism ; wp : organismName ?label . } Open List the species captured in WikiPathways and the number of pathways per species SELECT DISTINCT ?organism ( str ( ?label ) as ?name ) ( count ( ?pw ) as ?pathwayCount ) WHERE { ?pw dc : title ?title ; wp : organism ?organism ; wp : organismName ?label . } ORDER BY DESC ( ?pathwayCount ) Open List all pathways for species "Mus musculus" The following query list all mouse pathways. ?wpIdentifier is the link through identifiers.org, ?pathway points to the RDF version of WikiPathways and ?page is the revision which is loaded in the SPARQL endpoint. SELECT DISTINCT ?wpIdentifier ?pathway ?page WHERE { ?pathway dc : title ?title . ?pathway foaf : page ?page . ?pathway dc : identifier ?wpIdentifier . ?pathway wp : organismName "Mus musculus" . } ORDER BY ?wpIdentifier Open Get all pathways with a particular gene List all pathways per instance of a particular gene or protein ( wp:GeneProduct ) SELECT DISTINCT ?pathway ( str ( ?label ) as ?geneProduct ) WHERE { ?geneProduct a wp : GeneProduct . ?geneProduct rdfs : label ?label . ?geneProduct dcterms : isPartOf ?pathway . ?pathway a wp : Pathway . FILTER regex ( str ( ?label ), "CYP" ). } Open Get all groups and complexes containing a particular gene List all groups and complexes per instance of a particular gene or protein ( wp:GeneProduct ) SELECT DISTINCT ?pathway ( str ( ?label ) as ?geneProduct ) WHERE { ?geneProduct a wp : GeneProduct . ?geneProduct rdfs : label ?label . ?geneProduct dcterms : isPartOf ?pathway . FILTER NOT EXISTS { ?pathway a wp : Interaction } . FILTER NOT EXISTS { ?pathway a wp : Pathway } . FILTER regex ( str ( ?label ), "CYP" ). } Open Get all the genes on a particular pathway List all the genes and proteins ( wp:GeneProduct ) associated with a particular pathway WPID. select distinct ?pathway ( str ( ?label ) as ?geneProduct ) where { ?geneProduct a wp : GeneProduct . ?geneProduct rdfs : label ?label . ?geneProduct dcterms : isPartOf ?pathway . ?pathway a wp : Pathway . ?pathway dcterms : identifier "WP1560`,
